import{_ as a,c as i,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Networking in Node.js — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-05-networking.md","filePath":"practice/node-js/module-05-networking.md"}'),t={name:"practice/node-js/module-05-networking.md"};function o(s,e,l,c,d,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="networking-in-node-js-—-practice" tabindex="-1">Networking in Node.js — practice <a class="header-anchor" href="#networking-in-node-js-—-practice" aria-label="Permalink to “Networking in Node.js — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-05-networking.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="diagnostic-exercise" tabindex="-1"><span class="hub-section-number">1 </span>Diagnostic exercise <a class="header-anchor" href="#diagnostic-exercise" aria-label="Permalink to “1 Diagnostic exercise”">​</a></h3><p>Build a client for an unreliable local service.</p><p>Requirements:</p><ul><li>enforce one total deadline;</li><li>retry only safe failures with jitter;</li><li>use an idempotency key for a create operation;</li><li>reuse bounded connections;</li><li>stop retrying when the caller cancels;</li><li>record attempt count and stage timing;</li><li>prove that a dependency outage cannot create an unbounded request queue.</li></ul><hr><h2 id="_19-final-review-checklist" tabindex="-1"><span class="hub-section-number">2 </span>Final review checklist <a class="header-anchor" href="#_19-final-review-checklist" aria-label="Permalink to “2 Final review checklist”">​</a></h2><p>You should be able to explain and demonstrate each item:</p><h3 id="resilience-and-diagnosis" tabindex="-1"><span class="hub-section-number">2.1 </span>Resilience and diagnosis <a class="header-anchor" href="#resilience-and-diagnosis" aria-label="Permalink to “2.1 Resilience and diagnosis”">​</a></h3><ul><li>Propagate one time budget across connection, retry, and response work.</li><li>Retry only classified transient failures within a bounded attempt budget.</li><li>Explain why a timed-out write may have completed remotely.</li><li>Use an atomic idempotency record for safely repeated commands.</li><li>Reuse and bound connections instead of creating an unlimited connection burst.</li><li>Diagnose DNS, connection, TLS, first-byte, and body-transfer failures separately.</li><li>Configure proxy trust before relying on forwarded client information.</li></ul><h3 id="architecture-and-protocols" tabindex="-1"><span class="hub-section-number">2.2 </span>Architecture and protocols <a class="header-anchor" href="#architecture-and-protocols" aria-label="Permalink to “2.2 Architecture and protocols”">​</a></h3><ul><li>A client initiates communication; a server listens and responds.</li><li>One application can be both a server and a client in different interactions.</li><li>Stateless requests contain the context needed for each interaction.</li><li>Stateless servers can still use databases and caches.</li><li>DNS resolves names, TCP carries reliable ordered bytes, TLS secures a channel, and HTTP defines message semantics.</li><li>HTTPS is HTTP over TLS; SSL is obsolete terminology/protocol history.</li><li>WebSocket upgrades from HTTP to a persistent full-duplex message protocol.</li><li>Node.js 22 has a built-in WebSocket client but no built-in WebSocket server API.</li><li>TCP and stream chunks do not preserve application message boundaries.</li></ul><h3 id="http" tabindex="-1"><span class="hub-section-number">2.3 </span>HTTP <a class="header-anchor" href="#http" aria-label="Permalink to “2.3 HTTP”">​</a></h3><ul><li>A request has method, target, headers, and optional content.</li><li>A response has status, headers, and optional content.</li><li>Safe and idempotent describe method semantics, not whether internal logs change.</li><li>GET is safe/idempotent; PUT and DELETE are idempotent; POST and PATCH are not guaranteed idempotent.</li><li>RFC 10008 defines QUERY as a safe, idempotent content-bearing query method.</li><li><code>Content-Type</code> describes the sent body; <code>Accept</code> describes desired response formats.</li><li>Use status codes and headers as part of the API contract.</li><li><code>401</code> concerns authentication; <code>403</code> concerns permission.</li><li>A <code>204</code> or <code>304</code> response has no representation body.</li></ul><h3 id="node-js-apis" tabindex="-1"><span class="hub-section-number">2.4 </span>Node.js APIs <a class="header-anchor" href="#node-js-apis" aria-label="Permalink to “2.4 Node.js APIs”">​</a></h3><ul><li><code>http.IncomingMessage</code> is readable and <code>http.ServerResponse</code> is writable.</li><li>Return after ending a response.</li><li>Parse <code>request.url</code> with a base URL.</li><li>Bound request-body size before collecting it.</li><li>Parse JSON and then validate its runtime shape.</li><li><code>fetch()</code> does not reject for ordinary HTTP error statuses.</li><li>A fetch response body can normally be consumed only once.</li><li>Outbound calls need deadlines and deliberate retry rules.</li><li><code>node:https</code> serves TLS directly; infrastructure often terminates TLS instead.</li><li><code>node:net</code> exposes duplex TCP sockets and requires application framing.</li><li><code>dns.lookup()</code> follows OS-style resolution, while <code>resolve*()</code> queries record types.</li><li><code>URLSearchParams.getAll()</code> is needed for repeated query keys.</li></ul><h3 id="rest-and-api-design" tabindex="-1"><span class="hub-section-number">2.5 </span>REST and API design <a class="header-anchor" href="#rest-and-api-design" aria-label="Permalink to “2.5 REST and API design”">​</a></h3><ul><li>REST has six constraints; code on demand is the only optional one.</li><li>Uniform interface includes resource identification, representations, self-descriptive messages, and hypermedia.</li><li>Resource paths use stable nouns; HTTP methods carry operation semantics.</li><li>PUT represents replacement; PATCH represents partial modification.</li><li>Pagination, filtering, sorting, errors, and versioning need consistent contracts.</li><li>Idempotency keys can make retried non-idempotent operations safer when the server implements them correctly.</li><li><code>If-Match</code> plus ETag can prevent lost updates.</li><li>HATEOAS advertises discoverable links and currently valid actions.</li></ul><h3 id="caching-and-cors" tabindex="-1"><span class="hub-section-number">2.6 </span>Caching and CORS <a class="header-anchor" href="#caching-and-cors" aria-label="Permalink to “2.6 Caching and CORS”">​</a></h3><ul><li><code>no-cache</code> means revalidate before reuse; <code>no-store</code> means do not store.</li><li>ETag/<code>If-None-Match</code> can produce <code>304 Not Modified</code>.</li><li><code>Vary</code> tells caches which request headers affect response selection.</li><li>An origin consists of scheme, hostname, and port.</li><li>CORS is enforced by browsers and is not authentication or authorization.</li><li>Preflight uses <code>OPTIONS</code> for requests outside the CORS safelist.</li><li>Credentialed CORS cannot use wildcard <code>Access-Control-Allow-Origin</code>.</li><li>Dynamically origin-specific responses should include <code>Vary: Origin</code>.</li><li>CORS headers must appear on the actual response, not only preflight.</li></ul><h3 id="production-readiness" tabindex="-1"><span class="hub-section-number">2.7 </span>Production readiness <a class="header-anchor" href="#production-readiness" aria-label="Permalink to “2.7 Production readiness”">​</a></h3><ul><li>Validate and size-limit every untrusted network boundary.</li><li>Protect against SSRF when users influence outbound URLs.</li><li>Authenticate callers and authorize each resource action separately.</li><li>Do not log tokens, cookies, credentials, private keys, or unrestricted bodies.</li><li>Configure timeouts, cancellation, rate limits, and graceful shutdown.</li><li>Close servers, connections, timers, and subscriptions on every lifecycle path.</li><li>Test ordinary behavior, malformed input, dependency failure, timeout, disconnect, retry, and shutdown.</li></ul><h2 id="_20-boundary-failure-labs" tabindex="-1"><span class="hub-section-number">3 </span>Boundary failure labs <a class="header-anchor" href="#_20-boundary-failure-labs" aria-label="Permalink to “3 Boundary failure labs”">​</a></h2><p><strong>HTTP acceptance:</strong> run the handler on an ephemeral loopback port in a separate fixture. Valid UTF-8 application/json with parameters succeeds; application/jsonjunk, an unsupported charset, malformed media type and missing type reject415; malformed/empty/BOM/invalid-UTF8 JSON reject400. A tiny chunked upload exceeding the configured byte bound receives best-effort413 with Connection:close without waiting for unbounded input; a stalled body receives408 under the application deadline. A peer abort does not produce an unhandled error or leave a referenced timer. Confirm source listeners/collector buffers are released. The actual proxy/Expect100/HTTP2 policy still requires integration evidence.</p><p><strong>CORS acceptance:</strong> begin with Vary:Accept-Encoding and require Origin merged once. Repeat for allowed, denied and absent Origin; preserve Vary:* and case-insensitive existing entries. Preflight validates requested method/header names; unauthorized Origin or header/method receives403 and no wildcard credentials. Allowed actual response has explicit origin/credentials/exposed headers. Test ordinary OPTIONS independently. Browser SOP/cookie/preflight-cache behavior cannot be proven by a Node fetch or header double; record real browser observations separately.</p><p><strong>WebSocket acceptance:</strong> valid echo, malformed JSON, null/array/unknown fields, overlong ID/text, binary input, excessive payload/rate and slow send buffer follow their declared policy without throwing out of the callback. Verify close timer/listener cleanup and process shutdown with a real ws client/server. Test rejected/missing Origin and distinguish it from authenticated permission. Document replay/reconnect/heartbeat limitations rather than claiming the echo service supplies them. Learner practice and real service-scale security/load checks remain required.</p><p>References checked2026-10-21: <a href="https://nodejs.org/download/release/v24.18.0/docs/api/http.html" target="_blank" rel="noreferrer">Node24 HTTP lifecycle</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/util.html#class-utilmimetype" target="_blank" rel="noreferrer">MIMEType</a>, <a href="https://github.com/websockets/ws/blob/master/doc/ws.md" target="_blank" rel="noreferrer">ws API</a>, <a href="https://fetch.spec.whatwg.org/#http-cors-protocol" target="_blank" rel="noreferrer">Fetch CORS protocol</a>, <a href="https://www.rfc-editor.org/rfc/rfc10008.html" target="_blank" rel="noreferrer">RFC10008</a>. QUERY&#39;s June2026 standardization was verified and retained; implementation adoption still needs end-to-end checks.</p>',29)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
